// src/forkop/methods/shell/callBaseMethod.ts
async function callBaseMethod(method, args = [], command = "/usr/bin/forkop", options = {}) {
  try {
    const response = await executeShellCommand({
      command,
      args: [method, ...args],
      timeout: options.timeout ?? 15e3
    });
    const exitCode = response.code ?? 0;
    if (exitCode !== 0 && !(options.allowNonZeroWithStdout && response.stdout)) {
      return {
        success: false,
        error: response.stderr || response.stdout || ""
      };
    }
    if (response.stdout) {
      try {
        return {
          success: true,
          data: JSON.parse(response.stdout)
        };
      } catch (_e) {
        return {
          success: true,
          data: response.stdout
        };
      }
    }
    return {
      success: false,
      error: response.stderr || ""
    };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : ""
    };
  }
}

